/* ==========================================
   1) PARCHEO DE ESQUEMA SIN IF EXISTS/ALTER
   ========================================== */
DELIMITER $$

DROP PROCEDURE IF EXISTS sp_patch_schema_alumnos $$
CREATE PROCEDURE sp_patch_schema_alumnos()
BEGIN
  DECLARE v_exists INT DEFAULT 0;

  /* 1.a) Quitar columna alumnos.asesor_email si existe */
  SELECT COUNT(*) INTO v_exists
  FROM information_schema.columns
  WHERE table_schema = DATABASE()
    AND table_name = 'alumnos'
    AND column_name = 'asesor_email';
  IF v_exists = 1 THEN
    SET @sql := 'ALTER TABLE alumnos DROP COLUMN asesor_email';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* 1.b) Asegurar columna alumnos.asesor_id (si no existe) */
  SELECT COUNT(*) INTO v_exists
  FROM information_schema.columns
  WHERE table_schema = DATABASE()
    AND table_name = 'alumnos'
    AND column_name = 'asesor_id';
  IF v_exists = 0 THEN
    SET @sql := 'ALTER TABLE alumnos ADD COLUMN asesor_id INT NULL';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* 1.c) UNIQUE en alumnos.email (si no existe índice con ese nombre) */
  SELECT COUNT(*) INTO v_exists
  FROM information_schema.statistics
  WHERE table_schema = DATABASE()
    AND table_name = 'alumnos'
    AND index_name = 'uq_alumnos_email';
  IF v_exists = 0 THEN
    SET @sql := 'ALTER TABLE alumnos ADD CONSTRAINT uq_alumnos_email UNIQUE (email)';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* 1.d) UNIQUE en alumnos.matricula (si no existe índice con ese nombre) */
  SELECT COUNT(*) INTO v_exists
  FROM information_schema.statistics
  WHERE table_schema = DATABASE()
    AND table_name = 'alumnos'
    AND index_name = 'uq_alumnos_matricula';
  IF v_exists = 0 THEN
    SET @sql := 'ALTER TABLE alumnos ADD CONSTRAINT uq_alumnos_matricula UNIQUE (matricula)';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* 1.e) Índice para la FK (si asesor_id no tiene índice) */
  SELECT COUNT(*) INTO v_exists
  FROM information_schema.statistics
  WHERE table_schema = DATABASE()
    AND table_name = 'alumnos'
    AND column_name = 'asesor_id';
  IF v_exists = 0 THEN
    SET @sql := 'ALTER TABLE alumnos ADD INDEX idx_alumnos_asesor_id (asesor_id)';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* 1.f) FK alumnos -> teachers (si no existe con ese nombre) */
  SELECT COUNT(*) INTO v_exists
  FROM information_schema.table_constraints
  WHERE table_schema = DATABASE()
    AND table_name = 'alumnos'
    AND constraint_type = 'FOREIGN KEY'
    AND constraint_name = 'fk_alumnos_asesor';
  IF v_exists = 0 THEN
    SET @sql := 'ALTER TABLE alumnos
                 ADD CONSTRAINT fk_alumnos_asesor
                 FOREIGN KEY (asesor_id) REFERENCES teachers(id)';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

END $$
DELIMITER ;

CALL sp_patch_schema_alumnos();
DROP PROCEDURE sp_patch_schema_alumnos;

