-- 3) Backfill: vincula cada alumno a su id de generación
UPDATE alumnos a
JOIN generaciones g ON g.nombre = a.generacion
SET a.generacion_id = g.id
WHERE a.generacion IS NOT NULL AND a.generacion_id IS NULL;

-- 4) (Opcional recomendado) Deja UNIQUE lógico en generaciones.nombre por si no estaba
-- Ya existe segun el dump, pero no sobra:
-- ALTER TABLE generaciones ADD UNIQUE KEY (nombre);

-- 5) Vista para el módulo “Por generación”
DROP VIEW IF EXISTS vw_reporte_generaciones;
CREATE VIEW vw_reporte_generaciones AS
SELECT
  g.id                        AS generacion_id,
  g.nombre                    AS generacion,
  COUNT(a.id)                 AS alumnos_registrados,
  MIN(a.created_at)           AS primer_alta,
  MAX(a.updated_at)           AS ultima_actualizacion
FROM generaciones g
LEFT JOIN alumnos a ON a.generacion_id = g.id
GROUP BY g.id, g.nombre
ORDER BY g.created_at DESC, g.nombre;



