/* =======================================================
   1) GENERACIONES: COLUMNA FK EN ALUMNOS + VISTA REPORTE
   ======================================================= */
DELIMITER $$

DROP PROCEDURE IF EXISTS sp_add_generacion_fk $$
CREATE PROCEDURE sp_add_generacion_fk()
BEGIN
  DECLARE v INT DEFAULT 0;

  /* 1.a) Asegurar tabla generaciones */
  SELECT COUNT(*) INTO v
  FROM information_schema.tables
  WHERE table_schema = DATABASE()
    AND table_name = 'generaciones';

  IF v = 0 THEN
    SET @sql := '
      CREATE TABLE generaciones (
        id INT NOT NULL AUTO_INCREMENT,
        nombre VARCHAR(255) NOT NULL,
        created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (id),
        UNIQUE KEY uq_generaciones_nombre (nombre)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
    ';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* 1.b) Columna alumnos.generacion_id */
  SELECT COUNT(*) INTO v
  FROM information_schema.columns
  WHERE table_schema = DATABASE()
    AND table_name = 'alumnos'
    AND column_name = 'generacion_id';

  IF v = 0 THEN
    SET @sql := 'ALTER TABLE alumnos ADD COLUMN generacion_id INT NULL AFTER generacion';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* 1.c) Índice en alumnos.generacion_id */
  SELECT COUNT(*) INTO v
  FROM information_schema.statistics
  WHERE table_schema = DATABASE()
    AND table_name = 'alumnos'
    AND index_name = 'idx_alumnos_generacion_id';

  IF v = 0 THEN
    SET @sql := 'ALTER TABLE alumnos ADD INDEX idx_alumnos_generacion_id (generacion_id)';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* 1.d) Constraint FK hacia generaciones */
  SELECT COUNT(*) INTO v
  FROM information_schema.table_constraints
  WHERE table_schema = DATABASE()
    AND table_name   = 'alumnos'
    AND constraint_type = 'FOREIGN KEY'
    AND constraint_name = 'fk_alumnos_generacion';

  IF v = 0 THEN
    SET @sql := 'ALTER TABLE alumnos
                 ADD CONSTRAINT fk_alumnos_generacion
                 FOREIGN KEY (generacion_id) REFERENCES generaciones(id)';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;
END $$
DELIMITER ;

CALL sp_add_generacion_fk();
