SELECT
  g.id              AS generacion_id,
  g.nombre          AS generacion,
  COUNT(a.id)       AS alumnos_registrados,
  MIN(a.created_at) AS primer_alta,
  MAX(a.updated_at) AS ultima_actualizacion
FROM generaciones g
LEFT JOIN alumnos a ON a.generacion_id = g.id
GROUP BY g.id, g.nombre
ORDER BY g.created_at DESC, g.nombre;



