  IF v = 0 THEN
    SET @sql := 'ALTER TABLE alumnos ADD COLUMN carrera_id INT NULL';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* FK area_id -> areas_conocimiento */
  SELECT COUNT(*) INTO v
  FROM information_schema.table_constraints
  WHERE table_schema = DATABASE()
    AND table_name   = 'alumnos'
    AND constraint_type = 'FOREIGN KEY'
    AND constraint_name = 'fk_alumnos_area';

  IF v = 0 THEN
    SET @sql := 'ALTER TABLE alumnos
                 ADD CONSTRAINT fk_alumnos_area
                 FOREIGN KEY (area_id) REFERENCES areas_conocimiento(id)';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;

  /* FK carrera_id -> carreras */
  SELECT COUNT(*) INTO v
  FROM information_schema.table_constraints
  WHERE table_schema = DATABASE()
    AND table_name   = 'alumnos'
    AND constraint_type = 'FOREIGN KEY'
    AND constraint_name = 'fk_alumnos_carrera';

  IF v = 0 THEN
    SET @sql := 'ALTER TABLE alumnos
                 ADD CONSTRAINT fk_alumnos_carrera
                 FOREIGN KEY (carrera_id) REFERENCES carreras(id)';
    PREPARE s FROM @sql; EXECUTE s; DEALLOCATE PREPARE s;
  END IF;
END $$
DELIMITER ;

CALL sp_patch_area_carrera();
DROP PROCEDURE sp_patch_area_carrera;

/* ====== FIN DEL PARCHE DEPURADO ====== */
